//! Rhyme detection for song lyrics, built on the CMU Pronouncing Dictionary
//! (`assets/rhymes.txt`, generated by `assets/make_rhymes.py`, licence in `assets/CMUDICT-LICENSE`).
//!
//! A word's *rhyme tail* is its phonemes from the last stressed vowel to the end
//! (`mine` and `fine` are both `AY N`).
//!
//! Detection is local, so it works on a whole song with no blank lines:
//! * Candidates are the last word of each phrase (lines are split at `, . ; : ! ? -` and
//!   parentheses); words inside parentheses are never candidates.
//! * Two candidates can only link when they are close: line-end words within 3 lines,
//!   a mid-line phrase end only on the same or an adjacent line.
//! * Links come in three strengths (equal tail, slant, feminine/`-ing` ending); a weaker
//!   level is only tried for words the stronger ones did not already pair up.
//! * Linked candidates form groups (union-find); a group needs 2+ distinct spellings.
//! * Colours are assigned greedily so groups within 6 lines of each other differ.

use std::collections::HashMap;
use std::sync::OnceLock;

/// Number of colour groups the UI has; every `Mark::group` is below this.
pub const GROUPS: usize = 8;

/// A rhyming word: byte range inside its line, plus its colour-group index
/// (0 = the most frequent rhyme sound in the verse).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Mark {
    pub start: usize,
    pub end: usize,
    pub group: usize,
}

static DATA: &str = include_str!("../assets/rhymes.txt");

/// File layout: tail count, that many tail lines, then sorted `word code` lines
/// (code = base-36 index into the tails).
struct Dict {
    tails: Vec<&'static str>,
    words: Vec<&'static str>,
}

fn dict() -> &'static Dict {
    static D: OnceLock<Dict> = OnceLock::new();
    D.get_or_init(|| {
        let mut it = DATA.lines();
        let n: usize = it.next().and_then(|l| l.parse().ok()).unwrap_or(0);
        let tails = it.by_ref().take(n).collect();
        Dict {
            tails,
            words: it.collect(),
        }
    })
}

fn lookup(word: &str) -> Option<&'static str> {
    let d = dict();
    let i = d
        .words
        .binary_search_by(|l| l.split(' ').next().unwrap_or("").cmp(word))
        .ok()?;
    let code = d.words[i].split(' ').nth(1)?;
    d.tails.get(usize::from_str_radix(code, 36).ok()?).copied()
}

/// Words that are never *internal* rhyme candidates (they still count at a line end).
const STOP: &[&str] = &[
    "the", "a", "an", "i", "you", "me", "my", "we", "to", "in", "it", "is", "and", "of", "on",
    "for", "that", "this", "with", "but", "so", "up", "no", "oh", "yeah", "uh", "ah", "ay", "ooh",
    "hey", "he", "she", "they", "them", "us", "our", "your", "his", "her", "its", "at", "as", "be",
    "am", "are", "was", "were", "do", "did", "have", "has", "had", "or", "if", "then", "than",
    "not", "just", "all", "out", "off", "from", "by", "can", "will", "got", "get", "like", "what",
    "who", "how", "why", "when", "where", "there", "here", "too", "now", "i'm", "i'll", "i've",
    "i'd", "it's", "that's", "don't", "can't", "ain't", "you're", "we're", "they're", "he's",
    "she's", "what's", "let's", "gonna", "wanna", "gotta", "ya", "em", "cause", "uh-huh", "yo",
    "ha", "la", "na", "da",
];

struct Tok {
    start: usize,
    end: usize,
    text: String,
    paren: bool,
    /// Phrase number within the line; bumps at punctuation and parentheses.
    phrase: usize,
}

/// Letters plus apostrophes that follow a letter ("don't", "gettin'").
/// Phrases end at `, . ; : ! ? …`, dashes, parentheses and brackets. A hyphen between two
/// letters ("uh-huh", "mid-air") does not split. Words inside `( )` or `[ ]` are `paren`.
fn tokenize(line: &str) -> Vec<Tok> {
    let ch: Vec<(usize, char)> = line.char_indices().collect();
    let (mut toks, mut depth, mut phrase, mut i) = (Vec::new(), 0i32, 0usize, 0);
    while i < ch.len() {
        let c = ch[i].1;
        match c {
            '(' | '[' => {
                depth += 1;
                phrase += 1;
            }
            ')' | ']' => {
                depth = (depth - 1).max(0);
                phrase += 1;
            }
            ',' | '.' | ';' | ':' | '!' | '?' | '…' | '–' | '—' => phrase += 1,
            '-' => {
                let letter = |k: Option<&(usize, char)>| k.is_some_and(|x| x.1.is_alphabetic());
                if !(i > 0 && letter(ch.get(i - 1)) && letter(ch.get(i + 1))) {
                    phrase += 1;
                }
            }
            _ if c.is_alphabetic() => {
                let mut j = i + 1;
                while j < ch.len() {
                    let cj = ch[j].1;
                    let apos = (cj == '\'' || cj == '’') && ch[j - 1].1.is_alphabetic();
                    if cj.is_alphabetic() || apos {
                        j += 1;
                    } else {
                        break;
                    }
                }
                let (start, end) = (ch[i].0, ch.get(j).map_or(line.len(), |x| x.0));
                let text = line[start..end].replace('’', "'").to_lowercase();
                toks.push(Tok {
                    start,
                    end,
                    text,
                    paren: depth > 0,
                    phrase,
                });
                i = j;
                continue;
            }
            _ => {}
        }
        i += 1;
    }
    toks
}

/// Crude fallback for words missing from the dictionary: last vowel group plus the
/// letters after it, prefixed with `~` so it only ever equals another guessed tail.
fn spelling_tail(w: &str) -> Option<String> {
    let mut cs: Vec<char> = w.chars().filter(|c| c.is_alphabetic()).collect();
    if cs.len() < 3 {
        return None;
    }
    if cs.len() > 3 && cs.last() == Some(&'e') {
        cs.pop();
    }
    let vowel = |c: &char| "aeiouy".contains(*c);
    let mut s = cs.iter().rposition(vowel)?;
    while s > 0 && vowel(&cs[s - 1]) {
        s -= 1;
    }
    Some(format!("~{}", cs[s..].iter().collect::<String>()))
}

/// Rhyme-tail key for `w` (lowercase) and whether it came from the dictionary.
/// Tries: exact, dropped-g ("gettin'" -> "getting"), bare, "'s" removed, then spelling.
fn resolve(w: &str, guess: bool) -> Option<(String, bool)> {
    let find = |s: &str| lookup(s).map(str::to_string);
    let dropped_g = w.ends_with("in'");
    let mut hit = find(w);
    if hit.is_none() && dropped_g {
        hit = find(&format!("{}g", w.trim_end_matches('\'')));
    }
    let bare = w.trim_end_matches('\'');
    if hit.is_none() && bare.len() != w.len() && !dropped_g {
        hit = find(bare);
    }
    if hit.is_none() && bare.len() > 3 && bare.ends_with("in") {
        hit = find(&format!("{bare}g"));
    }
    if hit.is_none()
        && let Some(b) = w.strip_suffix("'s")
    {
        hit = find(b);
    }
    match hit {
        Some(mut t) => {
            // "-ing" and dropped-g "-in'" should rhyme with each other.
            let drop = dropped_g || (bare.ends_with("in") && !w.ends_with("ing"));
            let mut ph: Vec<&str> = t.split(' ').collect();
            let n = ph.len();
            if n >= 2 && (ph[n - 2..] == ["IH", "NG"] || (drop && ph[n - 2..] == ["AH", "N"])) {
                ph[n - 2..].copy_from_slice(&["IH", "N"]);
                t = ph.join(" ");
            }
            Some((t, true))
        }
        None if guess => spelling_tail(w).map(|t| (t, false)),
        None => None,
    }
}

struct Cand {
    line: usize,
    start: usize,
    end: usize,
    word: String,
    tail: String,
    exact: bool,
    /// Last non-ad-lib word of its line (as opposed to the end of a mid-line phrase).
    is_end: bool,
    /// Weak (feminine / "-ing") class, see `weak_class`.
    weak: Option<&'static str>,
}

const VOWELS: [&str; 15] = [
    "AA", "AE", "AH", "AO", "AW", "AY", "EH", "ER", "EY", "IH", "IY", "OW", "OY", "UH", "UW",
];

/// Slant key: the stressed vowel plus whether the trailing consonant is voiceless
/// (P T K F S TH SH CH HH). Everything else (nasals, liquids, voiced stops/fricatives,
/// or no consonant) counts as one voiced class, so mind/fine/high/time (AY + voiced)
/// match loosely while life/light (AY + voiceless) and cat/dog (different vowels) do not.
fn slant_key(tail: &str) -> (&str, bool) {
    let mut ph = tail.split(' ');
    let vowel = ph.next().unwrap_or("");
    let voiceless = matches!(
        ph.next_back(),
        Some("P" | "T" | "K" | "F" | "S" | "TH" | "SH" | "CH" | "HH")
    );
    (vowel, voiceless)
}

/// Vowels many accents say alike (the "cot/caught" merger, "Fanta" with the vowel of "cat"), so
/// two tails that differ only by one of these pairs still rhyme.
fn near_tail(a: &str, b: &str) -> bool {
    let (va, ra) = a.split_once(' ').unwrap_or((a, ""));
    let (vb, rb) = b.split_once(' ').unwrap_or((b, ""));
    ra == rb && matches!((va, vb), ("AA", "AE" | "AO") | ("AE" | "AO", "AA"))
}

/// Weak class for words with an unstressed ending: the final unstressed vowel
/// (Lisa/Atlanta/Fanta -> "AH"), or "ING" for the -ing / -in' family. A tail has at
/// least two vowels here, because it starts at the last *stressed* vowel.
fn weak_class(tail: &str) -> Option<&'static str> {
    let ph: Vec<&str> = tail.split(' ').collect();
    if ph.iter().filter(|p| VOWELS.contains(p)).count() < 2 {
        return None;
    }
    if ph.ends_with(&["IH", "N"]) {
        return Some("ING");
    }
    VOWELS.iter().find(|v| Some(*v) == ph.last()).copied()
}

/// Same idea from spelling alone, for words missing from the dictionary.
fn spelling_weak(w: &str) -> Option<&'static str> {
    if w.chars().count() < 5 {
        return None;
    }
    if w.ends_with("ing") || w.ends_with("in'") {
        Some("ING")
    } else if w.ends_with("er") || w.ends_with("or") || w.ends_with("ar") {
        Some("ER")
    } else if w.ends_with('a') {
        Some("AH")
    } else if w.ends_with('y') || w.ends_with("ey") || w.ends_with("ie") {
        Some("IY")
    } else {
        None
    }
}

/// The same word said again, or a simple variation of it (love/loves, lovin'/loving).
fn same_word(a: &str, b: &str) -> bool {
    let bases = |w: &str| -> Vec<String> {
        let w = match w.strip_suffix("in'") {
            Some(stem) => format!("{stem}ing"),
            None => w.trim_end_matches('\'').to_string(),
        };
        let mut all = vec![w.clone()];
        for suffix in ["ing", "ed", "es", "s"] {
            if let Some(base) = w.strip_suffix(suffix)
                && base.chars().count() >= 3
            {
                all.push(base.to_string());
            }
        }
        all
    };
    let other = bases(b);
    bases(a).iter().any(|base| other.contains(base))
}

/// Can `a` (earlier) and `b` be linked at `level`? 0 = equal tail, 1 = slant, 2 = weak.
/// A line ending on the same word again links at level 0, whatever its sound.
fn linkable(level: usize, a: &Cand, b: &Cand) -> bool {
    let d = b.line - a.line;
    let both_end = a.is_end && b.is_end;
    if same_word(&a.word, &b.word) {
        return level == 0 && both_end && d <= 3;
    }
    // Line-end words may be 3 lines apart; anything involving a mid-line phrase end only 1.
    let window = if both_end { 3 } else { 1 };
    match level {
        0 => d <= window && a.tail == b.tail,
        1 => {
            d <= window
                && a.exact
                && b.exact
                && (slant_key(&a.tail) == slant_key(&b.tail) || near_tail(&a.tail, &b.tail))
        }
        _ => both_end && d <= 2 && a.weak.is_some() && a.weak == b.weak,
    }
}

fn find(uf: &mut [usize], mut x: usize) -> usize {
    while uf[x] != x {
        uf[x] = uf[uf[x]];
        x = uf[x];
    }
    x
}

/// Finds rhymes in a run of lyric lines (a verse, or a whole song without blank lines).
/// Returns one `Vec<Mark>` per input line, sorted by `start`. Colour indices are local:
/// groups within 6 lines of each other never share one. Lines that are all identical
/// (a repeated hook) get no marks.
pub fn mark_verse(lines: &[&str]) -> Vec<Vec<Mark>> {
    let mut out = vec![Vec::new(); lines.len()];
    let norm = |l: &str| l.trim().to_lowercase();
    if lines.len() >= 2 && lines.iter().all(|l| norm(l) == norm(lines[0])) {
        return out;
    }

    // Candidates: the last word of every phrase, outside parentheses.
    let mut cands: Vec<Cand> = Vec::new();
    for (li, line) in lines.iter().enumerate() {
        let toks = tokenize(line);
        let end_idx = toks.iter().rposition(|t| !t.paren);
        for (ti, t) in toks.iter().enumerate() {
            let phrase_end = toks.get(ti + 1).is_none_or(|n| n.phrase != t.phrase);
            if t.paren || !phrase_end {
                continue;
            }
            let is_end = Some(ti) == end_idx;
            let Some((tail, exact)) = resolve(&t.text, true) else {
                continue;
            };
            let phonemes = tail.split(' ').count();
            let letters = t.text.chars().filter(|c| c.is_alphabetic()).count();
            if STOP.contains(&t.text.as_str()) {
                // "in", "me", "it" only count as a multi-phoneme line ending.
                if !is_end || phonemes < 2 {
                    continue;
                }
            } else if !is_end && phonemes < 2 && letters < 3 {
                continue;
            }
            let weak = if exact {
                weak_class(&tail)
            } else {
                spelling_weak(&t.text)
            };
            cands.push(Cand {
                line: li,
                start: t.start,
                end: t.end,
                word: t.text.trim_end_matches('\'').to_string(),
                tail,
                exact,
                is_end,
                weak,
            });
        }
    }

    // Link nearby candidates, strongest level first. After level 0, a pair is only
    // considered if at least one side is still unpaired, so two finished rhyme
    // groups are not glued together by a loose match.
    let n = cands.len();
    let mut uf: Vec<usize> = (0..n).collect();
    let mut paired = vec![false; n];
    for level in 0..3 {
        let mut links = Vec::new();
        for i in 0..n {
            for j in i + 1..n {
                if cands[j].line - cands[i].line > 3 {
                    break;
                }
                if level > 0 && paired[i] && paired[j] {
                    continue;
                }
                if linkable(level, &cands[i], &cands[j]) {
                    links.push((i, j));
                }
            }
        }
        for (i, j) in links {
            paired[i] = true;
            paired[j] = true;
            let (ri, rj) = (find(&mut uf, i), find(&mut uf, j));
            uf[ri] = rj;
        }
    }

    // Components with 2+ distinct words are rhyme groups.
    let mut comps: HashMap<usize, Vec<usize>> = HashMap::new();
    for i in 0..n {
        let r = find(&mut uf, i);
        comps.entry(r).or_default().push(i);
    }
    let mut comps: Vec<Vec<usize>> = comps.into_values().filter(|g| g.len() >= 2).collect();
    comps.sort_by_key(|g| g[0]);

    // Greedy colouring in order of first line. A group avoids the colours of earlier groups
    // that end within 6 lines of where it starts; with every colour taken, reuse the one
    // whose conflicting group ended longest ago.
    let span = |g: &Vec<usize>| {
        (
            cands[g[0]].line,
            g.iter().map(|&i| cands[i].line).max().unwrap_or(0),
        )
    };
    let mut colour = vec![0usize; comps.len()];
    for k in 0..comps.len() {
        let lo = span(&comps[k]).0;
        let mut last_use: [Option<usize>; GROUPS] = [None; GROUPS];
        for p in 0..k {
            let hi = span(&comps[p]).1;
            if lo <= hi + 6 {
                let slot = &mut last_use[colour[p]];
                *slot = Some(slot.map_or(hi, |h| h.max(hi)));
            }
        }
        colour[k] = (0..GROUPS)
            .find(|&c| last_use[c].is_none())
            .or_else(|| (0..GROUPS).min_by_key(|&c| last_use[c]))
            .unwrap_or(0);
    }

    for (g, &c) in comps.iter().zip(&colour) {
        for &i in g {
            let cd = &cands[i];
            out[cd.line].push(Mark {
                start: cd.start,
                end: cd.end,
                group: c,
            });
        }
    }
    for l in &mut out {
        l.sort_by_key(|m| m.start);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn words<'a>(line: &'a str, marks: &[Mark]) -> Vec<&'a str> {
        marks.iter().map(|m| &line[m.start..m.end]).collect()
    }

    fn none(l: &[&str]) -> bool {
        mark_verse(l).iter().all(|m| m.is_empty())
    }

    #[test]
    fn dictionary_lookup() {
        assert_eq!(lookup("mine"), Some("AY N"));
        assert_eq!(lookup("fine"), Some("AY N"));
        assert_eq!(lookup("zzzzqq"), None);
    }

    #[test]
    fn perfect_end_rhyme() {
        let l = [
            "I got the world in the palm of mine",
            "Everything is gonna be just fine",
        ];
        let m = mark_verse(&l);
        assert_eq!(words(l[0], &m[0]), ["mine"]);
        assert_eq!(words(l[1], &m[1]), ["fine"]);
        assert_eq!(m[0][0].group, m[1][0].group);
    }

    #[test]
    fn slant_end_rhyme() {
        let l = [
            "never gonna change my mind",
            "everything is feeling fine",
            "we reach up to the heavens so high",
        ];
        let m = mark_verse(&l);
        assert!(m.iter().all(|x| x.len() == 1), "{m:?}");
        assert_eq!(m[0][0].group, m[1][0].group);
        assert_eq!(m[0][0].group, m[2][0].group);
    }

    #[test]
    fn fanta_and_atlanta_rhyme_whatever_the_dictionary_says() {
        // the dictionary gives Fanta the vowel of "father", Atlanta the vowel of "cat"
        let l = ["flying out to see Atlanta", "sipping on a cold Fanta"];
        let m = mark_verse(&l);
        assert_eq!(words(l[0], &m[0]), ["Atlanta"]);
        assert_eq!(words(l[1], &m[1]), ["Fanta"]);
        assert_eq!(m[0][0].group, m[1][0].group);
    }

    #[test]
    fn cat_dog_do_not_rhyme() {
        assert!(none(&["I saw a cat", "I saw a dog"]));
    }

    #[test]
    fn mid_phrase_words_are_not_candidates() {
        // "night" is mid-phrase and "might" the only phrase end: nothing to pair.
        assert!(none(&["Fighting through the night with all my might"]));
        // After a comma, "line" is a phrase end and pairs with "fine" on the same line.
        let l = ["Hold the line, feeling fine"];
        assert_eq!(words(l[0], &mark_verse(&l)[0]), ["line", "fine"]);
    }

    #[test]
    fn adlib_is_not_the_end_word() {
        let l = [
            "Counting up the cash all night (what else?)",
            "Everything is looking right (yeah)",
        ];
        let m = mark_verse(&l);
        assert_eq!(words(l[0], &m[0]), ["night"]);
        assert_eq!(words(l[1], &m[1]), ["right"]);
    }

    #[test]
    fn words_in_parentheses_are_never_candidates() {
        assert!(none(&["Got it all (heat)", "Never gonna lose (street)"]));
    }

    #[test]
    fn stop_words_alone_do_not_light_up() {
        assert!(none(&["Come with me", "Over the sea"]));
        assert!(none(&["Never gonna give it", "Put it all in"]));
    }

    #[test]
    fn dropped_g_resolves() {
        let (a, ea) = resolve("gettin'", false).unwrap();
        let (b, eb) = resolve("rappin'", false).unwrap();
        assert!(ea && eb);
        assert_eq!(a, "IH T IH N");
        assert_eq!(b, "AE P IH N");
        let l = [
            "Every day I'm hustlin' and gettin'",
            "Never stopping always sittin'",
        ];
        let m = mark_verse(&l);
        assert_eq!(words(l[0], &m[0]), ["gettin'"]);
        assert_eq!(words(l[1], &m[1]), ["sittin'"]);
    }

    #[test]
    fn slang_in_dictionary() {
        assert!(resolve("tryna", false).is_some());
        assert!(resolve("ma", false).is_some());
        assert!(resolve("fanta", false).is_some());
    }

    #[test]
    fn a_repeated_end_word_is_a_rhyme() {
        // two identical lines are a repeated hook, not a rhyme
        assert!(none(&["I walk this road alone", "I walk this road alone"]));
        let m = mark_verse(&["I walk this road alone", "and I feel so alone"]);
        assert!(
            m.iter().all(|x| x.len() == 1) && m[0][0].group == m[1][0].group,
            "{m:?}"
        );
        // and it joins a group with a different word that rhymes
        let l = [
            "I walk this road alone",
            "and I feel so alone",
            "cold as a stone",
        ];
        let m = mark_verse(&l);
        assert!(m.iter().all(|x| x.len() == 1), "{m:?}");
        assert!(
            m[0][0].group == m[1][0].group && m[1][0].group == m[2][0].group,
            "{m:?}"
        );
    }

    #[test]
    fn a_chorus_that_changes_a_word_still_marks_its_repeats() {
        let l = [
            "Demons hold onto her hair",
            "She told me put my love over there",
            "She told me leave my love over there",
            "She told me put my love over there",
        ];
        let m = mark_verse(&l);
        let group = m[1][0].group;
        assert!(
            m[1..].iter().all(|x| x.len() == 1 && x[0].group == group),
            "{m:?}"
        );
    }

    #[test]
    fn variations_of_a_word_count_as_the_same_word() {
        assert!(same_word("love", "loves"));
        assert!(same_word("lovin'", "loving"));
        assert!(!same_word("tell", "tall"));
        assert!(!same_word("is", "as"));
    }

    #[test]
    fn repeated_hook_gets_nothing() {
        assert!(none(&["na na na hey", "na na na hey", "Na na na hey"]));
    }

    #[test]
    fn feminine_and_ing_families() {
        let l = [
            "dancing with a girl named Lisa",
            "flying out to see Atlanta",
            "sipping on a cold Fanta",
        ];
        let m = mark_verse(&l);
        assert!(m.iter().all(|x| x.len() == 1), "{m:?}");
        assert!(m[0][0].group == m[1][0].group && m[1][0].group == m[2][0].group);
        let l = [
            "windows down and riding",
            "over every hill we're sliding",
            "every word is convincing",
        ];
        let m = mark_verse(&l);
        assert!(m.iter().all(|x| x.len() == 1), "{m:?}");
        assert_eq!(m[0][0].group, m[2][0].group);
        // The weak rule only reaches 2 lines.
        assert!(none(&["girl named Lisa", "red", "blue", "see Fanta"]));
    }

    #[test]
    fn danger_stranger() {
        let l = ["I see the danger", "in every stranger"];
        let m = mark_verse(&l);
        assert_eq!(words(l[0], &m[0]), ["danger"]);
        assert_eq!(words(l[1], &m[1]), ["stranger"]);
    }

    #[test]
    fn rhymes_do_not_reach_across_the_song() {
        let far = [
            "on the green",
            "count the cash",
            "feel the rain",
            "hold the fort",
            "he is so lean",
        ];
        assert!(none(&far)); // 4 lines apart: out of window
        let near = [
            "on the green",
            "count the cash",
            "feel the rain",
            "he is so lean",
        ];
        assert!(!none(&near)); // 3 lines apart: linked
    }

    #[test]
    fn rap_verse() {
        let l = [
            "Woke up in the morning, grindin' on the block",
            "Tryna make a dollar while the whole world's on the clock",
            "Rolling through the city, ma, I'm never gonna stop",
            "Flexin' on the haters with the diamonds on my watch",
        ];
        let m = mark_verse(&l);
        assert_eq!(words(l[0], &m[0]).last(), Some(&"block"));
        assert_eq!(words(l[1], &m[1]).last(), Some(&"clock"));
        assert_eq!(m[0].last().unwrap().group, m[1].last().unwrap().group);
        assert!(m.iter().flatten().all(|k| k.group < GROUPS));
    }

    #[test]
    fn no_panics_on_odd_input() {
        let l = [
            "",
            "   ",
            "...!!!",
            "(just an adlib)",
            "日本語 のうた",
            "café olé olé",
            "'''",
            "naïve ’tis don’t",
            "1234 5678",
            "-",
            "((",
            "))word((",
            "a-",
        ];
        let m = mark_verse(&l);
        assert_eq!(m.len(), l.len());
        for (line, marks) in l.iter().zip(&m) {
            for k in marks {
                assert!(line.is_char_boundary(k.start) && line.is_char_boundary(k.end));
            }
        }
        assert!(mark_verse(&[]).is_empty());
    }

    #[test]
    fn colours_stay_in_range_with_many_groups() {
        let pairs = [
            "cat bat",
            "bear chair",
            "sky fly",
            "night light",
            "love dove",
            "moon spoon",
            "king ring",
            "hand land",
            "tree free",
            "rain pain",
            "star car",
        ];
        let l: Vec<String> = pairs
            .iter()
            .flat_map(|p| p.split(' ').map(|w| format!("x {w}")))
            .collect();
        let r: Vec<&str> = l.iter().map(|s| s.as_str()).collect();
        let m = mark_verse(&r);
        assert!(m.iter().flatten().all(|k| k.group < GROUPS));
        // Neighbouring couplets never share a colour.
        for i in (0..r.len() - 2).step_by(2) {
            assert_ne!(m[i][0].group, m[i + 2][0].group, "{m:?}");
        }
    }

    /// Made-up lyrics, no blank lines.
    const SONG: [&str; 16] = [
        "Walking through the city with a dream in my hand",
        "Building up an empire from a handful of sand",
        "Every night I'm out here on the road",
        "Carrying the weight of a heavy load",
        "Windows down and the music keeps riding",
        "Over every hill we keep sliding",
        "Every word I say is convincing",
        "Dancing in the lights with a girl named Lisa",
        "Flying out the door to go see Atlanta",
        "Sipping on a cold orange Fanta",
        "Money comes and goes but it never ends",
        "I keep a circle small of real friends",
        "Loyalty is where the story ends",
        "Looking at the stars on a quiet night",
        "Everything is feeling so right",
        "I can take it all and I am ready to stand",
    ];

    #[test]
    fn whole_song_without_blank_lines() {
        let m = mark_verse(&SONG);
        let marked: Vec<Vec<&str>> = SONG.iter().zip(&m).map(|(l, k)| words(l, k)).collect();
        let expect = [
            "hand",
            "sand",
            "road",
            "load",
            "riding",
            "sliding",
            "convincing",
            "Lisa",
            "Atlanta",
            "Fanta",
            "ends",
            "friends",
            "ends",
            "night",
            "right",
        ];
        for (i, w) in expect.iter().enumerate() {
            assert_eq!(marked[i], [*w], "line {i}");
        }
        // "stand" rhymes with "hand"/"sand" but is 15 and 14 lines away.
        assert!(m[15].is_empty());
        let g = |i: usize| m[i][0].group;
        // Same rhyme, same colour.
        assert_eq!(g(0), g(1));
        assert_eq!(g(2), g(3));
        assert!(g(4) == g(5) && g(5) == g(6));
        assert!(g(7) == g(8) && g(8) == g(9));
        assert!(g(10) == g(11) && g(11) == g(12));
        assert_eq!(g(13), g(14));
        // Groups a few lines apart never share a colour...
        for (a, b) in [(1, 2), (3, 4), (6, 7), (9, 10), (12, 13), (3, 7), (6, 10)] {
            assert_ne!(g(a), g(b), "lines {a} and {b}");
        }
        // ...but groups 15 lines apart may (colours are local, not frequency-ranked).
        assert_eq!(g(0), g(10));
        assert!(m.iter().flatten().all(|k| k.group < GROUPS));
    }
}
